.libPaths(c(Sys.getenv("VLIB"), .libPaths())); library(zugrpc)
seen <- new.env(); seen$req <- NULL
ok_resp <- function(req) { seen$req <- req; zuhttp::zu_response(200L, headers = c("content-type"="application/grpc"), body = as.raw(c(0,0,0,0,0)), trailers = c("grpc-status"="0")) }
mk <- function(...) grpc_channel("http://localhost:1", client = zuhttp::zu_client(transport = zuhttp::zu_mock_transport(ok_resp)), ...)
cls <- function(expr) tryCatch({force(expr); "ok"}, error = function(e) paste(class(e)[1], "|", conditionMessage(e)))
ch <- mk()
cat("F1 req:", cls(grpc_call(ch, "/a.B/C", raw(), metadata = c(req = "v"))), "\n")
cat("F1 r:  ", cls(grpc_call(ch, "/a.B/C", raw(), metadata = c(r = "v"))), "\n")
cat("F1 chan:", cls(mk(headers = c(r = "1"))), "then", cls(grpc_call(mk(headers = c(r = "1")), "/a.B/C", raw())), "\n")
cat("F2 dup:", cls(grpc_call(ch, "/a.B/C", raw(), metadata = c(a = "1", a = "2"))), "\n")
grpc_call(ch, "/a.B/C", raw(), metadata = c("user-agent"="one", "user-agent"="two"))
cat("F3 ua:", dQuote(seen$req$headers[tolower(names(seen$req$headers))=="user-agent"], FALSE), "\n")
grpc_call(ch, "/a.B/C", raw(), metadata = c("user-agent"=""))
cat("F4 ua:", dQuote(seen$req$headers[tolower(names(seen$req$headers))=="user-agent"], FALSE), "\n")
cat("F5 content-length accepted by encode:", cls(zugrpc:::metadata_encode(c("content-length"="99"))), "\n")
for (u in c("http://h:1\n", "http://:50051", "http://h:99999", "http://h:port")) cat("F6", deparse(u), cls(grpc_channel(u)), "\n")
cat("F6 call:", cls(grpc_call(grpc_channel("http://h:port"), "/a.B/C", raw())), "\n")
cat("F7:", cls(grpc_keepalive(time = 0.0004)), "then", cls(grpc_channel("http://h:1", keepalive = grpc_keepalive(time = 0.0004))), "\n")
print(grpc_keepalive(1234567, 7654321))
cat("F9:", zugrpc:::grpc_timeout(1e-16), zugrpc:::grpc_timeout(1e-12), "\n")
r10 <- function(req) zuhttp::zu_response(200L, headers = c("content-type"="application/grpc","grpc-status"="0"), body = as.raw(c(0,0,0,0,1,1)), trailers = c())
ch10 <- grpc_channel("http://localhost:1", client = zuhttp::zu_client(transport = zuhttp::zu_mock_transport(r10)))
cat("F10 unary:", cls(grpc_call(ch10, "/a.B/C", raw())), "\n")
st <- grpc_stream(ch10, "/a.B/C", raw()); st$next_message(); cat("F10 stream:", cls(st$next_message()), st$status(), "\n")
r11 <- function(req) zuhttp::zu_response(200L, headers = c("content-type"="text/html"), body = charToRaw("<html>hello</html>"), trailers = NULL)
ch11 <- grpc_channel("http://localhost:1", client = zuhttp::zu_client(transport = zuhttp::zu_mock_transport(r11)))
u <- tryCatch(grpc_call(ch11, "/a.B/C", raw()), error = identity); s <- tryCatch(grpc_stream(ch11, "/a.B/C", raw()), error = identity)
cat("F11 body unary:", length(u$body), " stream:", length(s$body), "\n")
ch12 <- grpc_channel("http://localhost:1", client = zuhttp::zu_client(transport = zuhttp::zu_mock_transport(ok_resp), query = list(q = "1"), headers = c("grpc-timeout"="1S")))
grpc_call(ch12, "/a.B/C", raw()); cat("F12 url:", seen$req$url, " grpc-timeout:", seen$req$headers[tolower(names(seen$req$headers))=="grpc-timeout"], "\n")
